import{z as l,x as s,o as e,c as d,q as n,j as r,D as B,d as A,s as i,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"数据供应商对照","description":"","frontmatter":{"title":"数据供应商对照","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-vendor-comparison.md","filePath":"quant/cn-vendor-comparison.md","lastUpdated":1791063341000}'),p={name:"quant/cn-vendor-comparison.md"};function D(m,E,u,F,C,h){const t=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=n('<h1 id="数据供应商对照" tabindex="-1">数据供应商对照 <a class="header-anchor" href="#数据供应商对照" aria-label="Permalink to &quot;数据供应商对照&quot;">​</a></h1><div class="epigraph"><p>回测事故里最贵的两类偏差——前视与幸存者——大多能追到采购合同：没买公告日字段、没买历史成分快照，工程再好也补不回来。</p><footer>—— 据交易所信息服务与信息披露制度口径整理</footer></div><p><a href="/quant/cn-fee-structure">上一课</a>把成本预算编到换手上界；预算再准，喂进策略的数据错了就全错。<a href="/quant/data-vendors">数据供应商对照</a>已写全球数据商的分层与采购逻辑，<a href="/quant/point-in-time">时点基本面</a>已写时点原则。本课对照中国数据生态的特殊结构：官方源、商业终端、开源接口与量化平台各占一层，而最大的暗坑不在覆盖而在时点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一个科目在三个日期上不同：报告期末、公告日、更正日；财报追溯调整后，历史数据被悄悄改写。同一只股票的复权价在不同商家的算法不同，除权日口径差直接改收益序列。指数成分的历史名单若无存档快照，用今天的成分表回测十年前就是幸存者偏差。这三件事在中国数据生态里都高发：披露的结构化程度参差、更正与追溯调整频繁，而多数商业终端默认只给「最新真相」。</p><p><span class="marginnote">术语翻译：「时点数据」（point-in-time）就是在每个历史时刻只使用当时已经公开的版本——回测 2018 年 4 月时，只能看到当时已公告的财报，而不是 2019 年更正后的版本。供应商默认只存「最新真相」，买时点数据相当于把历史上每个时刻的「当时真相」也一并买下来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分层采购加勾稽仲裁。底层官方源打底：交易所行情（Level-1 免费、Level-2 增值付费）、法定披露文件、登记结算的持仓与股东数据。中层商业终端做整合与检索，按五个维度对照选型：覆盖、时点质量、口径（复权、行业分类、停牌处理）、许可、工程接口；财务数据必须拿到公告日与更正史两个字段。外层开源接口与量化平台承接落地与实验：研究框架的数据层如 <a href="/quant/qlib-quant">Microsoft Qlib</a>，时序库如 <a href="/quant/dolphindb">DolphinDB</a>。勾稽次序固定：官方披露 &gt; 商业整合 &gt; 开源聚合，对不上以上游为准并留差异日志。许可边界单独立项：行情转发与再分发受交易所信息服务的合同约束，直接决定哪些数据能进生产、哪些只能留在研究环境。</p>',8)),(e(),r(o,null,{default:B(()=>[i(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20OFF%5B%22%E5%AE%98%E6%96%B9%E6%BA%90%EF%BC%9A%E8%A1%8C%E6%83%85%2F%E6%8A%AB%E9%9C%B2%2F%E7%99%BB%E8%AE%B0%E7%BB%93%E7%AE%97%22%5D%20--%3E%20MID%5B%22%E5%95%86%E4%B8%9A%E7%BB%88%E7%AB%AF%EF%BC%9A%E6%95%B4%E5%90%88%E4%B8%8E%E6%A3%80%E7%B4%A2%22%5D%0A%20%20OFF%20--%3E%20OPEN%5B%22%E5%BC%80%E6%BA%90%E6%8E%A5%E5%8F%A3%E4%B8%8E%E5%B9%B3%E5%8F%B0%E6%95%B0%E6%8D%AE%E5%B1%82%22%5D%0A%20%20MID%20--%3E%20PIT%5B%22%E7%82%B9%E6%97%B6%E5%BF%AB%E7%85%A7%EF%BC%9A%E5%85%AC%E5%91%8A%E6%97%A5%2B%E6%9B%B4%E6%AD%A3%E5%8F%B2%22%5D%0A%20%20OPEN%20--%3E%20PIT%0A%20%20PIT%20--%3E%20FACTOR%5B%22%E5%9B%A0%E5%AD%90%E5%BA%93%E4%B8%8E%E5%9B%9E%E6%B5%8B%22%5D%0A%20%20LIC%5B%22%E8%AE%B8%E5%8F%AF%E8%BE%B9%E7%95%8C%EF%BC%9A%E8%BD%AC%E5%8F%91%E4%B8%8E%E5%86%8D%E5%88%86%E5%8F%91%22%5D%20--%3E%20PROD%5B%22%E7%94%9F%E4%BA%A7%E5%87%86%E5%85%A5%E5%88%A4%E6%96%AD%22%5D%0A%20%20FACTOR%20--%3E%20PROD%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"生态形态是制度给的。行情是交易所特许经营的增值服务：深度行情付费、转发受限，这决定了数据成本的下限与再分发红线；披露是法定义务但颗粒度不均，商业终端的价值在整合与标准化，代价是抹平时点信息；开源接口近乎零成本，但稳定性与口径责任全在用户。三层勾稽才能既省成本又保时点正确。实践中把「更正史」当成采购的硬指标：没有它的数据库会在回测里用更正后的值，把一次业绩暴雷从历史里抹掉。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"常见误区：初学者选数据商先比覆盖面和价格，实际尽调的第一问应是「财务字段带不带公告日和更正史、成分名单给不给历史快照」。覆盖缺几只票可以靠第二来源补，时点信息一旦被抹掉，再贵的工程团队也修不回一个干净的历史样本。")],-1)),(e(),r(o,null,{default:B(()=>[i(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20ORIG%5B%22%E5%B9%B4%E6%8A%A5%E5%8E%9F%E7%89%88%E6%8A%AB%E9%9C%B2%22%5D%20--%3E%20ARC%5B%22%E5%AE%98%E6%96%B9%E6%8A%AB%E9%9C%B2%E5%BA%93%E5%AD%98%E6%A1%A3%22%5D%0A%20%20ARC%20--%3E%20FIX%5B%22%E6%9B%B4%E6%AD%A3%E5%85%AC%E5%91%8A%E5%8F%91%E5%B8%83%22%5D%0A%20%20FIX%20--%3E%20Q%7B%22%E4%BE%9B%E5%BA%94%E5%95%86%E4%BF%9D%E7%95%99%E6%9B%B4%E6%AD%A3%E5%8F%B2%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20OK%5B%22%E5%9B%9E%E6%B5%8B%E6%8C%89%E5%85%AC%E5%91%8A%E6%97%A5%E8%AF%BB%E5%BD%93%E6%9C%9F%E7%9C%9F%E7%9B%B8%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20OW%5B%22%E5%8E%86%E5%8F%B2%E5%80%BC%E8%A2%AB%E9%9D%99%E9%BB%98%E8%A6%86%E7%9B%96%22%5D%0A%20%20OW%20--%3E%20GONE%5B%22%E4%B8%9A%E7%BB%A9%E6%9A%B4%E9%9B%B7%E4%BB%8E%E6%A0%B7%E6%9C%AC%E4%B8%AD%E6%B6%88%E5%A4%B1%22%5D%0A%20%20GONE%20--%3E%20BIAS%5B%22%E5%9B%9E%E6%B5%8B%E8%99%9A%E9%AB%98%3A%20%E5%89%8D%E8%A7%86%E5%81%8F%E5%B7%AE%22%5D%0A%20%20OK%20--%3E%20GOOD%5B%22%E5%9B%9E%E6%B5%8B%E5%8F%AF%E5%A4%8D%E7%8E%B0%E5%BD%93%E6%97%B6%E7%9A%84%E5%86%B3%E7%AD%96%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<p>上图回答的问题：一次财报更正在数据栈里如何走向两种相反的结局。官方源存档了原版与更正版，供应商若保留更正史，回测能按公告日重现「当时市场看到什么」；若直接覆盖，暴雷就从历史里消失，回测收益被系统性抬高。</p><p><span class="marginnote">数字实例：一只股票 10 送 10，除权日价格从 40 元变 20 元。若一家供应商复权时四舍五入到分、另一家保留全精度，单日收益率就能差出万分之几；几千个交易日累积下来，两条「同一只股票」的收益序列可以相差好几个百分点——足以改变因子排序与多空名单。</span></p><p><span class="marginnote">财务数据的「更正史」比「数值」贵：同一份年报，更正公告可以把关键科目改掉一个量级；采购时少要这一个字段，研究端就要多养一套人工核对流程。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做商家排名与选型推荐；许可边界以采购合同与交易所信息服务协议为准；爬虫与另类数据的采集合规不在本课范围。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>中国数据栈分四层：官方源打底、商业终端整合、开源接口交叉、平台层落地。</li><li>时点是最大暗坑：财务数据必须带公告日与更正史，成分名单要历史快照。</li><li>勾稽次序固定官方 &gt; 商业 &gt; 开源，差异留日志。</li><li>许可边界决定生产准入：行情转发与再分发受合同约束。</li><li>出处：交易所信息服务与信息披露制度口径；时点通则见<a href="/quant/point-in-time">时点基本面</a>。</li></ul>',7))])}const _=l(p,[["render",D]]);export{f as __pageData,_ as default};
